      "source": "def _translate_ch_to_exc(ch: str) -> None:
    if ch == "\x03":
        raise KeyboardInterrupt()
    if ch == "\x04" and not WIN:
        raise EOFError()
    if ch == "\x1a" and WIN:
        raise EOFError()"
