    {
      "qualname": "src/click/core.py::Option.get_help_extra",
      "source": "def get_help_extra(self, ctx: Context) -> types.OptionHelpExtra:
    extra: types.OptionHelpExtra = {}
    if self.show_envvar:
        ev = self.envvar
        if ev is None:
            if (
                self.allow_from_autoenv
                and ctx.auto_envvar_prefix is not None
                and self.name is not None
            ):
                ev = f"{ctx.auto_envvar_prefix}_{self.name.upper()}"
        if ev is not None:
            extra["envvars"] = (ev,) if isinstance(ev, str) else tuple(str(d) for d in ev)
    resilient = ctx.resilient_parsing
    ctx.resilient_parsing = True
    try:
        dv = self.get_default(ctx, call=False)
    finally:
        ctx.resilient_parsing = resilient
    sd = self.show_default
    sdis = False
    if sd is not None:
        if isinstance(sd, str):
            sdis = sd = True
        else:
            sd = sd
    elif ctx.show_default is not None:
        sd = ctx.show_default
    if sdis or (sd and dv not in (None, UNSET)):
        if sdis:
            ds = f"({self.show_default})"
        elif isinstance(dv, (list, tuple)):
            ds = ", ".join(str(d) for d in dv)
        elif isinstance(dv, enum.Enum):
            ds = dv.name
        elif inspect.isfunction(dv):
            ds = _("(dynamic)")
        elif self.is_bool_flag and self.secondary_opts:
            ds = _split_opt((self.opts if dv else self.secondary_opts)[0])[1]
        elif self.is_bool_flag and not self.secondary_opts and not dv:
            ds = ""
        elif isinstance(dv, str) and dv == "":
            ds = '""'
        else:
            ds = str(dv)
        if ds:
            extra["default"] = ds
    if (
        isinstance(self.type, types._NumberRangeBase)
        and not (self.count and self.type.min == 0 and self.type.max is None)
    ):
        rs = self.type._describe_range()
        if rs:
            extra["range"] = rs
    if self.required:
        extra["required"] = "required"
    return extra"
    },
    {
      "qualname": "src/click/core.py::Option.process_value",
      "source": "def process_value(self, ctx: Context, value: t.Any) -> t.Any:
    if self.is_flag and not self.required and self.is_bool_flag and value is UNSET:
        value = False
        if self.callback is not None:
            value = self.callback(ctx, self, value)
        return value
    return super().process_value(ctx, value)"
